  // ── State fiscal-year quarters (Jul–Jun) ──────────────────────────────────
  // The reporting basis is the state FY, because the funding line, the invoice
  // cadence and the Chancellor's Office all run on it.
  function fyOf(d) {
    var m = d.getUTCMonth();               // 0 = Jan
    var fyStart = (m >= 6) ? d.getUTCFullYear() : d.getUTCFullYear() - 1;
    var q = (m >= 6 && m <= 8) ? 1 : (m >= 9) ? 2 : (m <= 2) ? 3 : 4;
    return { fyStart: fyStart, q: q };
  }
  function fyLabel(fyStart) { return fyStart + "-" + pad2((fyStart + 1) % 100); }
  function periodLabel(fyStart, q) { return fyLabel(fyStart) + " Q" + q; }
  function quarterBounds(fyStart, q) {
    var startMonth = [6, 9, 0, 3][q - 1];                 // Jul, Oct, Jan, Apr
    var year = (q <= 2) ? fyStart : fyStart + 1;
    var start = new Date(Date.UTC(year, startMonth, 1));
    var end = new Date(Date.UTC(year, startMonth + 3, 0)); // last day of the quarter
    return { start: start, end: end };
  }
  // Every reporting period from execution through expiry. Built from the
  // contract's own dates — never a hardcoded list.
  function periodsFor(contract) {
    var startISO = contract.term_executed || contract.term_start_est;
    var s = parseISO(startISO), e = parseISO(contract.term_end);
    if (!s || !e) return [];
    var a = fyOf(s), b = fyOf(e), out = [];
    var fy = a.fyStart, q = a.q, guard = 0;
    while (guard++ < 80) {
      var bounds = quarterBounds(fy, q);
      out.push({
        label: periodLabel(fy, q), fy: fyLabel(fy), q: q,
        start: bounds.start, end: bounds.end
      });
      if (fy === b.fyStart && q === b.q) break;
      q += 1; if (q > 4) { q = 1; fy += 1; }
    }
    return out;
  }
  function currentPeriodLabel(now) {
    var f = fyOf(now);
    return periodLabel(f.fyStart, f.q);
  }

